#!/usr/bin/env python3
"""memcore 安装脚本（免 sudo）。

用法：
    python3 setup.py install            # 安装到 ~/.local
    python3 setup.py install --prefix ~/.local
    python3 setup.py develop            # 开发模式（当前目录可导入）
    python3 setup.py uninstall

设计约束：
- 不写 /usr /opt 等系统目录，不需要 root
- 不依赖 pip 联网；安装即拷贝纯 Python 包
- 提供 ~/.local/bin/memcore 启动脚本
"""

import argparse
import os
import shutil
import stat
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
PKG = HERE / "memcore"
LAUNCHER = """#!/bin/sh
# memcore launcher (generated by setup.py)
MEMCORE_HOME="${MEMCORE_HOME:-$HOME/.local/share/memcore}"
MEMCORE_DB_PATH="${MEMCORE_DB_PATH:-$MEMCORE_HOME/memories.db}"
export MEMCORE_HOME MEMCORE_DB_PATH
PYTHONPATH="__PKG_ROOT__${PYTHONPATH:+:$PYTHONPATH}"
export PYTHONPATH
exec "__PYTHON__" -m memcore "$@"
"""


def install(prefix: Path, dry_run: bool = False) -> int:
    prefix = prefix.expanduser()
    lib_dir = prefix / "lib" / "memcore"
    bin_dir = prefix / "bin"
    target_pkg = lib_dir / "memcore"

    steps = []
    if not dry_run:
        lib_dir.mkdir(parents=True, exist_ok=True)
        bin_dir.mkdir(parents=True, exist_ok=True)
        if target_pkg.exists():
            shutil.rmtree(target_pkg)
        shutil.copytree(PKG, target_pkg, ignore=shutil.ignore_patterns("__pycache__", "*.pyc"))
        launcher = bin_dir / "memcore"
        launcher.write_text(
            LAUNCHER.replace("__PKG_ROOT__", str(lib_dir)).replace("__PYTHON__", sys.executable),
            encoding="utf-8",
        )
        launcher.chmod(launcher.stat().st_mode | stat.S_IEXEC | stat.S_IXGRP | stat.S_IXOTH)
    steps.append(f"package -> {target_pkg}")
    steps.append(f"launcher -> {bin_dir / 'memcore'}")

    print("memcore 安装完成：")
    for s in steps:
        print(f"  {s}")
    print("")
    print("把 PATH 加上（写入 ~/.bashrc）：")
    print(f'  export PATH="{bin_dir}:$PATH"')
    print("")
    print("验证：")
    print(f'  {bin_dir / "memcore"} doctor')
    print(f'  {bin_dir / "memcore"} remember "示例记忆" --kind pref')
    print(f'  {bin_dir / "memcore"} recall "示例"')
    return 0


def uninstall(prefix: Path, dry_run: bool = False) -> int:
    prefix = prefix.expanduser()
    lib_dir = prefix / "lib" / "memcore"
    bin_dir = prefix / "bin" / "memcore"
    if not dry_run:
        if lib_dir.exists():
            shutil.rmtree(lib_dir)
        if bin_dir.exists():
            bin_dir.unlink()
    print(f"已移除 {lib_dir} 与 {bin_dir}（数据仍在 ~/.local/share/memcore）")
    return 0


def main() -> int:
    ap = argparse.ArgumentParser(description="memcore 安装器")
    ap.add_argument("action", choices=["install", "uninstall", "develop"])
    ap.add_argument("--prefix", default=os.environ.get("MEMCORE_PREFIX", "~/.local"))
    ap.add_argument("--dry-run", action="store_true")
    args = ap.parse_args()

    prefix = Path(args.prefix)
    if args.action == "install":
        return install(prefix, args.dry_run)
    if args.action == "uninstall":
        return uninstall(prefix, args.dry_run)
    # develop：把仓库根加进当前 PYTHONPATH
    print(f'export PYTHONPATH="{HERE}:$PYTHONPATH"')
    print(f'export PATH="{HERE / "bin"}:$PATH"')
    return 0


if __name__ == "__main__":
    sys.exit(main())
